def flip_bit(n: int, k: int) -> int:
    return n ^ (1 << k)


def is_bit_set(n: int, k: int) -> bool:
    return (n & (1 << k)) != 0


n, k = map(int, input().split())
flipped = flip_bit(n, k)
print(flipped)
print("true" if is_bit_set(flipped, k) else "false")

